import functools
from typing import ForwardRef, Any
from fastapi.dependencies.utils import get_typed_signature
import inspect
import pytest

def test_wrapped_method_type_inference():
    class Target:
        pass

    def my_endpoint(x: "Target"):
        return {"x": x}

    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_endpoint = wrapper(my_endpoint)

    # Remove Target from current globals to force failure if it uses current globals
    # (which wrapped_endpoint.__globals__ points to)
    global Target
    del Target

    try:
        sig = get_typed_signature(wrapped_endpoint)
        assert sig.parameters['x'].annotation is not inspect.Parameter.empty
    except NameError as e:
        pytest.fail(f"Raised NameError: {e}")

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
EOF
